def countDivisibleSubsets(nums, k):
    MOD = 10 ** 9 + 7
    dp = [0] * k
    dp[0] = 1
    for x in nums:
        x %= k
        new = dp[:]
        for r in range(k):
            if dp[r]:
                new[(r + x) % k] = (new[(r + x) % k] + dp[r]) % MOD
        dp = new
    return (dp[0] - 1) % MOD
